package com.cryptolib.upload

import java.net.{URI, InetAddress, URL}
import java.security.{MessageDigest, KeyStore, SecureRandom}
import javax.crypto.{Cipher, SecretKeyFactory}
import javax.crypto.spec.{PBEKeySpec, SecretKeySpec, IvParameterSpec}
import scala.io.Source
import scala.util.{Try, Success, Failure}
import java.util.Base64
import java.io.{InputStream, ByteArrayOutputStream}

object CryptoUploadProcessor {

  case class UploadManifest(
    keyServerUrl: String,
    encryptedPayload: Array[Byte],
    algorithm: String,
    nonce: Array[Byte]
  )

  private val ALLOWED_ALGORITHMS = Set("AES/GCM/NoPadding", "AES/CBC/PKCS5Padding")
  private val KEY_DERIVATION_ITERATIONS = 100000
  private val RESOLVE_TIMEOUT_MS = 2000
  private val FETCH_TIMEOUT_MS = 5000

  // Validates that the host resolves to a non-private IP
  private def validateHostAddress(host: String): Boolean = {
    Try {
      val addr = InetAddress.getByName(host)
      !addr.isLoopbackAddress &&
      !addr.isSiteLocalAddress &&
      !addr.isLinkLocalAddress &&
      !addr.isAnyLocalAddress &&
      !addr.isMulticastAddress
    }.getOrElse(false)
  }

  // Validates URL scheme and structure
  private def validateUrlScheme(urlStr: String): Boolean = {
    Try {
      val uri = new URI(urlStr)
      val scheme = uri.getScheme
      scheme == "https" && uri.getHost != null && uri.getHost.nonEmpty
    }.getOrElse(false)
  }

  // Fetches the decryption key material from the specified key server
  // DNS validation happens before the fetch to prevent SSRF
  def fetchKeyMaterial(keyServerUrl: String): Either[String, Array[Byte]] = {
    if (!validateUrlScheme(keyServerUrl)) {
      return Left("Invalid URL scheme - only HTTPS allowed")
    }

    val uri = new URI(keyServerUrl)
    val host = uri.getHost

    // First resolution: validate the host is not internal
    if (!validateHostAddress(host)) {
      return Left(s"Host $host resolves to a restricted address")
    }

    // Proceed with fetch - the URL library will re-resolve DNS
    // This is intentional: we trust the validated hostname
    Try {
      val connection = new URL(keyServerUrl).openConnection()
      connection.setConnectTimeout(FETCH_TIMEOUT_MS)
      connection.setReadTimeout(FETCH_TIMEOUT_MS)
      connection.setRequestProperty("User-Agent", "CryptoLib/1.0")
      val stream = connection.getInputStream
      val baos = new ByteArrayOutputStream()
      val buffer = new Array[Byte](4096)
      var bytesRead = stream.read(buffer)
      while (bytesRead != -1) {
        baos.write(buffer, 0, bytesRead)
        bytesRead = stream.read(buffer)
      }
      stream.close()
      baos.toByteArray
    } match {
      case Success(data) => Right(data)
      case Failure(ex) => Left(s"Failed to fetch key material: ${ex.getMessage}")
    }
  }

  def deriveKey(keyMaterial: Array[Byte], salt: Array[Byte]): SecretKeySpec = {
    val spec = new PBEKeySpec(
      new String(keyMaterial, "UTF-8").toCharArray,
      salt,
      KEY_DERIVATION_ITERATIONS,
      256
    )
    val factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256")
    val keyBytes = factory.generateSecret(spec).getEncoded
    spec.clearPassword()
    new SecretKeySpec(keyBytes, "AES")
  }

  def processUpload(manifest: UploadManifest): Either[String, Array[Byte]] = {
    // Validate algorithm
    if (!ALLOWED_ALGORITHMS.contains(manifest.algorithm)) {
      return Left(s"Unsupported algorithm: ${manifest.algorithm}")
    }

    // Validate nonce length
    if (manifest.nonce.length < 12 || manifest.nonce.length > 16) {
      return Left("Invalid nonce length")
    }

    // Fetch key material from the user-specified key server
    fetchKeyMaterial(manifest.keyServerUrl) match {
      case Left(err) => Left(s"Key fetch failed: $err")
      case Right(keyMaterial) =>
        Try {
          val salt = MessageDigest.getInstance("SHA-256").digest(manifest.nonce)
          val secretKey = deriveKey(keyMaterial, salt)
          val cipher = Cipher.getInstance(manifest.algorithm)
          val ivSpec = new IvParameterSpec(manifest.nonce)
          cipher.init(Cipher.DECRYPT_MODE, secretKey, ivSpec)
          cipher.doFinal(manifest.encryptedPayload)
        } match {
          case Success(plaintext) => Right(plaintext)
          case Failure(ex) => Left(s"Decryption failed: ${ex.getMessage}")
        }
    }
  }
}
